import { MedusaService } from "@medusajs/framework/utils"

import { PetProductProfile, PetProductSpecies } from "./models"

/**
 * The Pet Product Module owns `pet_product_species`,
 * `pet_product_profile` and the generated `pet_product_profile_species` pivot
 * table. Every method is generated by `MedusaService` from the models.
 *
 * It does NOT own the relationship to a Medusa product: that lives in a module
 * link so the Product Module never has to know about this module.
 */
class PetProductModuleService extends MedusaService({
  PetProductProfile,
  PetProductSpecies,
}) {}

export default PetProductModuleService
